        cursor = conn.cursor()
        cursor.execute("EXEC [dbo].[sp_leadCaptures] @pjsonfile = %s", (json.dumps(json_file),))
        # Upsert SP returns ONE row, ONE column -- use fetchone()[0]
        row = cursor.fetchone()
        json_result = row[0] if row and row[0] else '{"message": "ok"}'

