export interface LeadCapture {
  leadCaptureId: number;
  companyId?: number | null;
  fullName: string;
  email: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource: string;
  interestArea?: string | null;
  status: string;
  assignedTo?: number | null;
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string | null;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

export interface CreateLeadCapturePublicPayload {
  fullName: string;
  email: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource: string;
  interestArea?: string | null;
  privacyConsentAccepted: boolean;
}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number | null, filters?: { status?: string; interestArea?: string; search?: string }): Promise<LeadCapture[]> {
  const payload: { leadCaptures: { companyId?: number | null; status?: string; interestArea?: string; search?: string }[] } = {
    leadCaptures: [{}]
  };

  if (companyId !== null) {
    payload.leadCaptures[0].companyId = companyId;
  }

  if (filters?.status) {
    payload.leadCaptures[0].status = filters.status;
  }
  if (filters?.interestArea) {
    payload.leadCaptures[0].interestArea = filters.interestArea;
  }
  if (filters?.search) {
    payload.leadCaptures[0].search = filters.search;
  }

  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// GET ONE — POST /one_leadCaptures
export async function getLeadCapture(leadCaptureId: number, companyId: number | null): Promise<LeadCapture> {
  const payload: { leadCaptures: { leadCaptureId: number; companyId?: number | null }[] } = {
    leadCaptures: [{ leadCaptureId }]
  };
  if (companyId !== null) {
    payload.leadCaptures[0].companyId = companyId;
  }
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  if (!data.leadCaptures || data.leadCaptures.length === 0) {
    throw new Error("LeadCapture not found");
  }
  return data.leadCaptures[0];
}

// CREATE — action: 1 (Public endpoint, companyId omitted as per ADR-001)
export async function createLeadCapturePublic(payload: CreateLeadCapturePublicPayload): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  const result = await res.json(); // Always parse JSON to check for embedded error
  if (!res.ok || result.error) {
    throw new Error(result.error || "Failed to create lead capture");
  }
  return result;
}

// UPDATE — action: 2
export async function updateLeadCapture(id: number, companyId: number | null, payload: Partial<LeadCapture>): Promise<LeadCapture> {
  const requestPayload: { action: 2; leadCaptureId: number; companyId?: number | null } & Partial<LeadCapture> = {
    action: 2,
    leadCaptureId: id,
    ...payload,
  };
  if (companyId !== null) {
    requestPayload.companyId = companyId;
  }

  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [requestPayload] }),
  });
  const result = await res.json();
  if (!res.ok || result.error) {
    throw new Error(result.error || "Failed to update lead capture");
  }
  return result;
}

// DELETE — action: 3
export async function deleteLeadCapture(id: number, companyId: number | null): Promise<void> {
  const requestPayload: { action: 3; leadCaptureId: number; companyId?: number | null } = {
    action: 3,
    leadCaptureId: id,
  };
  if (companyId !== null) {
    requestPayload.companyId = companyId;
  }

  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [requestPayload] }),
  });
  const result = await res.json(); // Always parse JSON to check for embedded error
  if (!res.ok || result.error) {
    throw new Error(result.error || "Failed to delete lead capture");
  }
}
