      if (initialLoad) {
        setLeads(newLeads);
      } else {
        setLeads((prevLeads) => [...prevLeads, ...newLeads]);
      }

      // Simple pagination logic, assuming API returns all filtered results
      // and we handle client-side pagination for infinite scroll if necessary.
      // For now, assuming `getAll` returns a full list, we'll slice it.
      const startIndex = initialLoad ? 0 : leads.length;
      const endIndex = startIndex + PAGE_SIZE;
      const paginatedLeads = newLeads.slice(startIndex, endIndex);

      if (initialLoad) {
        setLeads(paginatedLeads);
