              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, fullName: e.detail.value! }))}
              className={formErrors.fullName ? 'ion-invalid ion-touched' : ''}
              errorText={formErrors.fullName}
            />
            <IonInput
              fill="outline"
              label="Email *"
              labelPlacement="floating"
              type="email"
              value={formState.email}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, email: e.detail.value! }))}
              className={formErrors.email ? 'ion-invalid ion-touched' : ''}
              errorText={formErrors.email}
            />
            <IonInput
              fill="outline"
              label="Nombre de la Empresa"
              labelPlacement="floating"
              value={formState.companyName}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, companyName: e.detail.value! }))}
            />
            <IonInput
              fill="outline"
              label="Teléfono"
              labelPlacement="floating"
              type="tel"
              value={formState.phone}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
            />
            <IonInput
              fill="outline"
              label="Puesto de Trabajo"
              labelPlacement="floating"
              value={formState.jobTitle}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, jobTitle: e.detail.value! }))}
            />
            <IonInput
              fill="outline"
              label="Mensaje"
              labelPlacement="floating"
              value={formState.message}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, message: e.detail.value! }))}
            />
            <IonSelect
              fill="outline"
              label="Fuente del Lead *"
              labelPlacement="floating"
              value={formState.leadSource}
              onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, leadSource: e.detail.value! }))}
              interface="popover"
              className={formErrors.leadSource ? 'ion-invalid ion-touched' : ''}
              errorText={formErrors.leadSource}
            >
              {LEAD_SOURCE_OPTIONS.map((source) => (
                <IonSelectOption key={source} value={source}>
                  {source}
                </IonSelectOption>
              ))}
            </IonSelect>
            <IonSelect
              fill="outline"
              label="Área de Interés"
              labelPlacement="floating"
              value={formState.interestArea}
              onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, interestArea: e.detail.value! }))}
              interface="popover"
            >
              {INTEREST_AREA_OPTIONS.map((area) => (
                <IonSelectOption key={area} value={area}>
                  {area}
                </IonSelectOption>
              ))}
            </IonSelect>
            {editingLead && (
              <IonSelect
                fill="outline"
                label="Estado"
                labelPlacement="floating"
                value={formState.status}
                onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, status: e.detail.value! }))}
                interface="popover"
              >
                {LEAD_STATUS_OPTIONS.map((status) => (
                  <IonSelectOption key={status} value={status}>
                    {status}
                  </IonSelectOption>
                ))}
              </IonSelect>
            )}
            <IonItem className="ion-no-padding privacy-consent">
              <IonLabel>
                Acepto la política de privacidad *
              </IonLabel>
              <IonInput
                type="checkbox"
                slot="end"
                checked={formState.privacyConsentAccepted}
                onIonChange={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, privacyConsentAccepted: e.detail.checked as boolean }))}
                className={formErrors.privacyConsentAccepted ? 'ion-invalid ion-touched' : ''}
                errorText={formErrors.privacyConsentAccepted}
              />
            </IonItem>
          </IonContent>
          <div className="ion-padding">
            <IonButton expand="block" onClick={handleSaveLead} disabled={loading}>
              {loading ? <IonSpinner name="dots" /> : 'Guardar Lead'}
            </IonButton>
            <IonButton expand="block" fill="outline" onClick={() => setShowFormModal(false)}>
              Cancelar
            </IonButton>
          </div>
        </IonModal>
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
